const wh = $input.first().json;
const body = (wh.application_id !== undefined) ? wh : (wh.body || wh);

if (!body.application_id || !body.callback_url) {
  throw new Error('Dados em falta: application_id=' + body.application_id + ' callback_url=' + body.callback_url);
}

const skills      = String(body.candidate_skills     || '').slice(0, 2000);
const summary     = String(body.candidate_summary    || '').slice(0, 1000);
const experience  = String(body.candidate_experience || '').slice(0, 2000);
const jobTitle    = String(body.job_title            || '');
const requirements = String(body.job_requirements   || '').slice(0, 3000);

const prompt =
  'Es um especialista em recrutamento. Analisa a correspondencia entre o candidato e a vaga abaixo.\n\n' +
  'CANDIDATO:\n' +
  '- Competencias: ' + skills + '\n' +
  '- Resumo: ' + summary + '\n' +
  '- Experiencia: ' + experience + '\n\n' +
  'VAGA:\n' +
  '- Titulo: ' + jobTitle + '\n' +
  '- Requisitos: ' + requirements + '\n\n' +
  'Responde APENAS com um objecto JSON plano com dois campos:\n' +
  'similarity_score: um numero inteiro entre 0 e 100 representando a percentagem de correspondencia.\n' +
  'match_feedback: uma frase em portugues com os pontos fortes e as lacunas do candidato em relacao aos requisitos.';

return [{ json: {
  application_id: body.application_id,
  callback_url:   body.callback_url,
  ollamaModel:    'qwen2.5:3b',
  ollamaStream:   false,
  ollamaFormat:   'json',
  ollamaPrompt:   prompt,
}}];

const ollamaResp = $input.first().json;
const prev = $('Preparar Pedido Score').first().json;

function findNumeric(obj, names) {
  if (obj == null) return undefined;
  if (typeof obj === 'number') return obj;
  if (typeof obj === 'string') { const n = parseFloat(obj); return isNaN(n) ? undefined : n; }
  if (typeof obj !== 'object') return undefined;
  for (const k of Object.keys(obj)) {
    if (names.includes(k.toLowerCase())) {
      const v = obj[k];
      if (typeof v === 'number') return v;
      if (typeof v === 'string') { const n = parseFloat(v); if (!isNaN(n)) return n; }
    }
  }
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object') {
      const nested = findNumeric(v, names);
      if (nested !== undefined) return nested;
    }
  }
  return undefined;
}

function findText(obj, names) {
  if (obj == null) return undefined;
  if (typeof obj !== 'object') return undefined;
  for (const k of Object.keys(obj)) {
    if (names.includes(k.toLowerCase())) {
      const v = obj[k];
      if (typeof v === 'string' && v.trim().length > 0) return v.trim();
      if (typeof v === 'object' && v !== null) {
        const parts = [];
        for (const kk of Object.keys(v)) {
          const vv = v[kk];
          if (typeof vv === 'string') parts.push(vv);
        }
        if (parts.length) return parts.join(' ');
      }
    }
  }
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object') {
      const nested = findText(v, names);
      if (nested !== undefined) return nested;
    }
  }
  return undefined;
}

let parsed = {};
try {
  const raw = String(ollamaResp.response || '{}');
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  parsed = JSON.parse(cleaned);
  if (typeof parsed === 'number') parsed = { similarity_score: parsed };
  if (typeof parsed !== 'object' || parsed === null) parsed = {};
} catch (_) {}

const scoreRaw    = findNumeric(parsed, ['similarity_score','score','match_score','similarity','percentage','match_percentage']);
const feedbackRaw = findText(parsed,    ['match_feedback','feedback','explanation','analysis','comentario','analise','justification']);

return [{ json: {
  application_id: prev.application_id,
  callback_url:   prev.callback_url,
  similarity_score: Math.min(100, Math.max(0, parseFloat(scoreRaw) || 0)),
  match_feedback:   (feedbackRaw || 'Analise concluida.').toString().slice(0, 4000),
}}];
